      "example": "csharp solution\n\npublic int MaxArea(int[] h) {\n    int l=0,r=h.Length-1,best=0;\n    while(l<r) {\n        best=Math.Max(best,Math.Min(h[l],h[r])*(r-l));\n        if(h[l]<h[r]) l++; else r--;\n    }\n    return best;\n}\n\npython solution\n\ndef max_area(h):\n    l, r, best = 0, len(h)-1, 0\n    while l < r:\n        best = max(best, min(h[l],h[r])*(r-l))\n        if h[l] < h[r]: l += 1\n        else: r -= 1\n    return best\n\njava solution\n\npublic int maxArea(int[] h) {\n    int l=0,r=h.length-1,best=0;\n    while(l<r) {\n        best=Math.max(best,Math.min(h[l],h[r])*(r-l));\n        if(h[l]<h[r]) l++; else r--;\n    }\n    return best;\n}",
